BEGIN;
ALTER TABLE public.redirect_workspace_members DROP CONSTRAINT redirect_workspace_members_pending_tenant_fence;
ALTER TABLE public.redirect_workspace_invitations DROP CONSTRAINT redirect_workspace_invitations_pending_tenant_fence;
DO $$ DECLARE fence text; BEGIN
 SELECT conname INTO fence FROM pg_constraint WHERE conrelid='public.redirect_workspaces'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%status%provisioning%is_legacy%';
 IF fence IS NULL THEN RAISE EXCEPTION 'Missing activation fixture fence';END IF;
 EXECUTE format('ALTER TABLE public.redirect_workspaces DROP CONSTRAINT %I',fence);
END $$;
DO $$ DECLARE actor uuid:=gen_random_uuid();owner_id uuid:=gen_random_uuid();workspace uuid:=gen_random_uuid();invitation uuid:=gen_random_uuid();member uuid;result jsonb; BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(actor,'source-invite@example.org',now()),(owner_id,'source-owner@example.org',now());
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(workspace,'Recipient source workspace','recipient-source-workspace');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(workspace,owner_id);
 INSERT INTO public.redirect_workspace_invitations(id,workspace_id,email,label,role,token_hash,created_by) VALUES(invitation,workspace,'source-invite@example.org','Expected viewer','viewer',repeat('d',64),owner_id);
 PERFORM set_config('role','service_role',true);
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor,'x-qg-redirect-workspace','malformed-visitor-selection')::text,true);
 IF(public.redirect_invitation_inbox(actor)->>'count')::int<>0 THEN RAISE EXCEPTION 'Provisioning invitation disclosed';END IF;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Provisioning invitation accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_workspaces SET status='active' WHERE id=workspace;
 result:=public.redirect_invitation_inbox(actor);
 IF result#>>'{data,0,workspace,id}'<>workspace::text OR result#>>'{data,0,workspace,name}'<>'Recipient source workspace' OR(result->>'count')::int<>1 OR result::text LIKE '%token_hash%' OR result::text LIKE '%source-invite@example.org%' THEN RAISE EXCEPTION 'Inbox source metadata or recipient privacy failed';END IF;
 BEGIN PERFORM public.redirect_workspace_invitation(owner_id,'accept',invitation);RAISE EXCEPTION 'Wrong session actor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',owner_id)::text,true);
 BEGIN PERFORM public.redirect_workspace_invitation(owner_id,'accept',invitation);RAISE EXCEPTION 'Wrong recipient accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor)::text,true);
 UPDATE public.redirect_workspace_invitations SET revoked_at=now() WHERE id=invitation;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Revoked invitation accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_workspace_invitations SET revoked_at=NULL,expires_at=now()-interval '1 minute' WHERE id=invitation;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Expired invitation accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_workspace_invitations SET expires_at=now()+interval '1 day' WHERE id=invitation;
 UPDATE redirect_internal.workspace_owners SET active=false WHERE workspace_id=workspace;
 IF(public.redirect_invitation_inbox(actor)->>'count')::int<>0 THEN RAISE EXCEPTION 'Former Owner invitation discovered';END IF;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Former Owner invitation accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE redirect_internal.workspace_owners SET active=true WHERE workspace_id=workspace;
 result:=public.redirect_workspace_invitation(actor,'accept',p_hash=>repeat('d',64));member:=(result->>'memberId')::uuid;
 IF result#>>'{workspace,id}'<>workspace::text OR result->>'role'<>'viewer' OR NOT EXISTS(SELECT FROM public.redirect_workspace_members WHERE id=member AND workspace_id=workspace AND user_id=actor AND role='viewer') THEN RAISE EXCEPTION 'Acceptance did not join the source';END IF;
 IF public.redirect_workspace_invitation(actor,'accept',invitation)->>'memberId'<>member::text THEN RAISE EXCEPTION 'Acceptance replay changed membership';END IF;
 IF(public.redirect_invitation_inbox(actor)->>'count')::int<>0 THEN RAISE EXCEPTION 'Accepted invitation remained pending';END IF;
 UPDATE public.redirect_workspace_members SET role='member' WHERE id=member;
 IF public.redirect_workspace_invitation(actor,'accept',invitation)->>'role'<>'member' THEN RAISE EXCEPTION 'Acceptance replay overwrote current role';END IF;
 UPDATE public.redirect_workspace_members SET active=false WHERE id=member;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Inactive member reactivated';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_workspace_members SET active=true WHERE id=member;
 UPDATE redirect_internal.workspace_owners SET active=false WHERE workspace_id=workspace;
 IF(public.redirect_invitation_inbox(actor)->>'count')::int<>0 THEN RAISE EXCEPTION 'Former Owner invitation discovered';END IF;
 BEGIN PERFORM public.redirect_workspace_invitation(actor,'accept',invitation);RAISE EXCEPTION 'Former Owner invitation accepted';EXCEPTION WHEN no_data_found THEN NULL;END;
END $$;
ROLLBACK;
